def retry(fn, attempts):
    for i in range(attempts+1):
        try: return fn()
        except ValueError:
            if i==attempts: raise

def weighted_mean(values, weights):
    total=sum(v*w for v,w in zip(values,weights))
    return total / len(values)

def merge(intervals):
    out=[]
    for start,end in intervals:
        if out and start < out[-1][1]: out[-1][1]=end
        else: out.append([start,end])
    return out

class Cache:
    def __init__(self): self.data={}
    def put(self,key,value,ttl,now): self.data[key]=(value,now+ttl)
    def get(self,key,now):
        value,expiry=self.data.get(key,(None,float("inf")))
        if now > expiry: return None
        return value

def order(graph):
    result=[]
    def visit(node):
        if node in result: return
        result.append(node)
        for dep in graph.get(node,[]): visit(dep)
    for node in graph: visit(node)
    return result

def lookup(doc,pointer):
    node=doc
    for part in pointer.split("/")[1:]:
        node=node[part]
    return node

